const data = $input.first().json;

const emaCurrent = data.ema_current_status || 'UNKNOWN';
const actCurrent = data.act_current_status || 'UNKNOWN';
const actCurrentSeconds = data.act_current_seconds ?? 999999;

const lastAlert = data.last_alert_description || '';
const isBatteryAlertActive = lastAlert === 'BATERIA_AGOTADA';

let alertType = 'NONE';
let message = '';
let notifDescription = '';

const isActuatorOnline = actCurrent === 'ONLINE' || actCurrent === 'REBOOT' || actCurrentSeconds < 300;

// -------------------------------------------------------------------
// MÁQUINA DE ESTADOS FINITA (FSM) DE NOTIFICACIONES EMA
// Transiciones estrictas:
// Caso A (Batería Agotada) <-> Caso B (Operativo)
// -------------------------------------------------------------------

// CASO A: Transición a BATERÍA AGOTADA
// Condición: EMA está OFFLINE, Actuador está ONLINE (sistema operativo),
// Y NO hay una alerta de batería activa en Telegram.
if (emaCurrent === 'OFFLINE' && isActuatorOnline && !isBatteryAlertActive) {
  alertType = 'BATERIA_AGOTADA';
  notifDescription = 'BATERIA_AGOTADA';
  message = '\u200B\n<b>Batería Agotada / Sin Respuesta</b>\n\n<b>Nodo EMA:</b> OFFLINE\n<b>Nodo Actuador:</b> ONLINE\n\nEl nodo Estación Meteorológica (EMA) se encuentra sin batería o fuera de servicio.';
}
// CASO B: Transición a NODO EMA OPERATIVO
// Condición: EMA volvió a ONLINE (o SLEEP tras transmitir telemetría),
// Y TENÍAMOS una alerta de batería agotada previamente activa en Telegram (Caso A).
else if ((emaCurrent === 'ONLINE' || emaCurrent === 'SLEEP') && isBatteryAlertActive) {
  alertType = 'EMA_RESTABLECIDO';
  notifDescription = 'EMA_RESTABLECIDO';
  message = '\u200B\n<b>Nodo EMA</b> Operativo.\n\nEl nodo Estación Meteorológica ha reanudado la comunicación y enviado telemetría.';
}

if (alertType === 'NONE') {
  return [];
}

return [{
  json: {
    alertType,
    message,
    notifDescription
  }
}];
